import random
import re

MAX_N = 10**18
REFERENCE_LIMIT = 512
SAMPLES = ((20, 5), (400, 24), (1234567890, 42413))
SMALL_CASES = (1, 2, 3, 4, 5, 6, 7, 8, 15, 16, 17, 18, 19, 20, 399, 400, 401)


def _decimal_integer(text: str) -> int | None:
    token = text.strip()
    if re.fullmatch(r"[+-]?[0-9]+", token) is None:
        return None

    negative = token.startswith("-")
    digits = token.lstrip("+-").lstrip("0")
    if len(digits) > len(str(MAX_N)):
        # This magnitude exceeds every admissible input and output.
        magnitude = MAX_N + 1
    else:
        magnitude = int(digits or "0")
    return -magnitude if negative else magnitude


def validate_input(inp: str) -> bool:
    limit = _decimal_integer(inp)
    return limit is not None and 1 <= limit <= MAX_N


def gen_small(seed: int, n: int) -> list[str]:
    rng = random.Random(seed)
    cases = []
    for index in range(n):
        if index < len(SMALL_CASES):
            limit = SMALL_CASES[index]
        elif rng.randrange(4) == 0:
            limit = rng.randint(9, REFERENCE_LIMIT)
        else:
            limit = rng.randint(1, 8)
        cases.append(f"{limit}\n")
    return cases


def gen_stress(seed: int) -> list[str]:
    rng = random.Random(seed)
    b = 500_000_000 - rng.randint(1, 10_000)
    return [f"{MAX_N}\n", f"{4 * b * b - 1}\n"]


def check_postconditions(inp: str, out: str) -> list[tuple[str, str]]:
    limit = _decimal_integer(inp)
    if limit is None or not 1 <= limit <= MAX_N:
        return [("POST-1", "Expected one integer N in the allowed range.")]

    count = _decimal_integer(out)
    if count is None:
        return [("POST-2", "Expected one decimal integer token.")]

    if not int(limit >= 2) <= count <= limit // 2:
        return [("POST-4", "The count is outside the bounds for this N.")]

    for sample_limit, sample_count in SAMPLES:
        if limit == sample_limit and count != sample_count:
            return [("POST-3", f"The stated count for N={limit} is {sample_count}.")]

        if (limit < sample_limit and count > sample_count) or (
            limit > sample_limit and count < sample_count
        ):
            return [
                ("POST-5", f"The count violates monotonicity with N={sample_limit}.")
            ]

    return []


def metamorphic_pairs(seed: int, n: int) -> list[tuple[str, str, str, str]]:
    rng = random.Random(seed)
    pairs = []
    for index in range(n):
        if index == 0:
            relation, lower, upper = "equal", 2, 3
        elif index == 1:
            relation, lower, upper = "le", 1, 2
        elif index == 2:
            relation, lower, upper = "equal", MAX_N - 2, MAX_N - 1
        elif index == 3:
            relation, lower, upper = "le", MAX_N - 1, MAX_N
        elif index % 2 == 0:
            lower = 2 * rng.randint(1, (MAX_N - 1) // 2)
            relation, upper = "equal", lower + 1
        else:
            lower = rng.randint(1, MAX_N - 1)
            relation, upper = "le", rng.randint(lower + 1, MAX_N)
        pairs.append(("POST-5", relation, f"{lower}\n", f"{upper}\n"))
    return pairs


def _has_witness(value: int) -> bool:
    a = 1
    while 2**a <= value:
        b = 1
        while 2**a * b**2 <= value:
            if 2**a * b**2 == value:
                return True
            b += 1
        a += 1
    return False


def reference_small(inp: str) -> str | None:
    limit = _decimal_integer(inp)
    if limit is None or not 1 <= limit <= REFERENCE_LIMIT:
        return None

    count = sum(_has_witness(value) for value in range(1, limit + 1))
    return f"{count}\n"
